{
  "purpose": "Implements the core data extraction and transformation engine, base specification types, path navigation, and exception hierarchy for glom.",
  "responsibilities": [
    "Defines core specifier primitives such as Path, Spec, Coalesce, Call, Invoke, Ref, and Val for composing transformations.",
    "Provides the target singleton TType (T) for target-relative expressions and navigation.",
    "Implements the exception hierarchy including GlomError, PathAccessError, PathAssignError, CoalesceError, BadSpec, and UnregisteredTarget.",
    "Formats execution scopes and errors into structured multi-line and single-line diagnostic traces."
  ],
  "key_symbols": [
    {
      "entity_id": "glom/core.py::glom.core.GlomError",
      "behaviour": "Serves as the base exception for all errors raised during glom evaluation and provides error-wrapping capabilities."
    },
    {
      "entity_id": "glom/core.py::glom.core.Path",
      "behaviour": "Specifies explicit step-by-step navigation paths across data structures and handles path parsing, inspection, and traversal."
    },
    {
      "entity_id": "glom/core.py::glom.core.Spec",
      "behaviour": "Encapsulates a glom specification for deferred or repeated execution against targets."
    },
    {
      "entity_id": "glom/core.py::glom.core.Coalesce",
      "behaviour": "Specifies fallback behavior, evaluating a list of sub-specifiers until one succeeds without raising access errors."
    },
    {
      "entity_id": "glom/core.py::glom.core.Call",
      "behaviour": "Specifies executing a function with the current target passed as an argument."
    },
    {
      "entity_id": "glom/core.py::glom.core.Invoke",
      "behaviour": "Invokes callables with configurable constant or spec-evaluated arguments and keyword arguments."
    },
    {
      "entity_id": "glom/core.py::glom.core.Ref",
      "behaviour": "Allows naming sub-specifications and referencing them elsewhere within the same spec tree."
    },
    {
      "entity_id": "glom/core.py::glom.core.TType",
      "behaviour": "Provides a singleton target object (T) enabling expressions relative to the current target."
    },
    {
      "entity_id": "glom/core.py::glom.core.Val",
      "behaviour": "Wraps a literal value that evaluates directly without being processed as a specifier."
    },
    {
      "entity_id": "glom/core.py::glom.core.format_target_spec_trace",
      "behaviour": "Unpacks an execution scope into a multi-line diagnostic summary detailing the target and spec evaluation state."
    }
  ]
}
